static void hanoi(int *src, int *srcSize, int *aux, int *auxSize, int *dst, int *dstSize, int n) {
  if (n == 0) return;
  hanoi(src, srcSize, dst, dstSize, aux, auxSize, n - 1);
  dst[(*dstSize)++] = src[--(*srcSize)];
  hanoi(aux, auxSize, src, srcSize, dst, dstSize, n - 1);
}

void hanota(int *A, int ASize, int *B, int BSize, int *C, int *CSize) {
  hanoi(A, &ASize, B, &BSize, C, &CSize, ASize);
}

class Solution {
  void hanoi(vector<int> &src, vector<int> &aux, vector<int> &dst, int n) {
    if (n == 0) return;
    hanoi(src, dst, aux, n - 1);
    dst.push_back(src.back());
    src.pop_back();
    hanoi(aux, src, dst, n - 1);
  }

public:
  void hanota(vector<int> &A, vector<int> &B, vector<int> &C) {
    hanoi(A, B, C, A.size());
  }
};

func hanota(A []int, B []int, C []int) []int {
	var hanoi func(src, aux, dst *[]int, n int)
	hanoi = func(src, aux, dst *[]int, n int) {
		if n == 0 {
			return
		}
		hanoi(src, dst, aux, n-1)
		*dst = append(*dst, (*src)[len(*src)-1])
		*src = (*src)[:len(*src)-1]
		hanoi(aux, src, dst, n-1)
	}
	hanoi(&A, &B, &C, len(A))
	return C
}

class Solution {
  private void hanoi(List<Integer> src, List<Integer> aux, List<Integer> dst, int n) {
    if (n == 0) return;
    hanoi(src, dst, aux, n - 1);
    dst.add(src.remove(src.size() - 1));
    hanoi(aux, src, dst, n - 1);
  }

  public void hanota(List<Integer> A, List<Integer> B, List<Integer> C) {
    hanoi(A, B, C, A.size());
  }
}

class Solution:
    def hanota(self, A: List[int], B: List[int], C: List[int]) -> None:
        def hanoi(src, aux, dst, n):
            if n == 0:
                return
            hanoi(src, dst, aux, n - 1)
            dst.append(src.pop())
            hanoi(aux, src, dst, n - 1)

        hanoi(A, B, C, len(A))

impl Solution {
  pub fn hanota(a: &mut Vec<i32>, b: &mut Vec<i32>, c: &mut Vec<i32>) {
    fn hanoi(src: &mut Vec<i32>, aux: &mut Vec<i32>, dst: &mut Vec<i32>, n: usize) {
      if n == 0 {
        return;
      }
      hanoi(src, dst, aux, n - 1);
      let v = src.pop().unwrap();
      dst.push(v);
      hanoi(aux, src, dst, n - 1);
    }
    let n = a.len();
    hanoi(a, b, c, n);
  }
}

const hanota = (A: number[], B: number[], C: number[]): void => {
  const hanoi = (src: number[], aux: number[], dst: number[], n: number) => {
    if (n === 0) return;
    hanoi(src, dst, aux, n - 1);
    dst.push(src.pop()!);
    hanoi(aux, src, dst, n - 1);
  };
  hanoi(A, B, C, A.length);
};
